import base64, hashlib, json, pathlib, zipfile
entries = json.loads(r'''[{"name": "WakeMiniAgent.exe", "date": [2026, 11, 8, 9, 23, 14], "system": 0, "attr": 2180972544, "sha256": "36dd2122799869cbd5cc500d7cd4a0ff3f5fc235215d3f6326a7b5a0de0e89f0", "data": null}, {"name": "THIRD-PARTY-NOTICES.txt", "date": [2026, 11, 8, 9, 22, 32], "system": 0, "attr": 2176188416, "sha256": "8a3be2595ac98b0c399fba81a7cfdd6dbeb0f5b9551ff7e9b19e4be5f27d21a1", "data": ""}, {"name": "README.md", "date": [2026, 11, 8, 9, 22, 32], "system": 0, "attr": 2176188416, "sha256": "b06e654aeaf11aa6ad2b53bf199dcdcd8272e0bc11b7dbd84efef73f8dbafd90", "data": ""}, {"name": "WakeMini-Alice-Cloud-1.5.1.zip", "date": [2026, 11, 8, 9, 23, 14], "system": 0, "attr": 2176188416, "sha256": "a6037d11584b5b55bb8c2aa12a84feeecb9fb6f45e7360c44d56d213fc546f61", "data": ""}, {"name": "chrome-voice-extension/background.js", "date": [2026, 11, 8, 9, 22, 32], "system": 0, "attr": 2176188416, "sha256": "c1938f61c41bebde1e52948e85434930b3b0239803f9723a22bd6b5fcf4e4da9", "data": ""}, {"name": "chrome-voice-extension/content.js", "date": [2026, 11, 8, 9, 22, 32], "system": 0, "attr": 2176188416, "sha256": "79adfc36e60097f929365ac59691b580106e8257700a7273ece828480617b9ba", "data": ""}, {"name": "chrome-voice-extension/manifest.json", "date": [2026, 11, 8, 9, 22, 32], "system": 0, "attr": 2176188416, "sha256": "ecfa4dff1a336e4c2a26602cfa15481570a5ae38d116c717bd62468d6d0d46c8", "data": ""}]''')
out = pathlib.Path('release')
out.mkdir(exist_ok=True)
bundle = out / 'WakeMini-1.5.1-preview.zip'
with zipfile.ZipFile(bundle, 'w', zipfile.ZIP_DEFLATED) as archive:
    for item in entries:
        data = pathlib.Path('artifact/WakeMiniAgent.exe').read_bytes() if item['data'] is None else base64.b64decode(item['data'])
        assert hashlib.sha256(data).hexdigest() == item['sha256'], item['name']
        info = zipfile.ZipInfo(item['name'], tuple(item['date']))
        info.compress_type = zipfile.ZIP_DEFLATED
        info.create_system = item['system']
        info.external_attr = item['attr']
        archive.writestr(info, data)
with zipfile.ZipFile(bundle) as archive:
    assert archive.testzip() is None
checksum = hashlib.sha256(bundle.read_bytes()).hexdigest()
(out / 'SHA256SUMS.txt').write_text(checksum + '  ' + bundle.name + '\n')
print('All seven files match the delivered preview; ZIP SHA256:', checksum)
